-- Owner-authorized operational activation, November 20, 2026 Pacific.
-- Target only Family First Life - Chris Garness. No provider/send/DDL operation.
-- This is a one-time data operation; never replay after a successful commit.
BEGIN;
SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='60s';
DO $activate$
DECLARE
 target_org uuid:='a0000000-0000-0000-0000-000000000001';
 expected_functions jsonb:=$functions$[{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_accept_sms","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"d92d99658ccd650e12e0ac623d955be7"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_activation_guard","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"a92db61c6589beb55a02c208265f79b9"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_actor_claims","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"c880df9a4ac4fd677a1710a7445d23f2"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_admit_original","proconfig":["search_path=pg_catalog, pg_temp"],"prosecdef":true,"definition_md5":"298cceaaf17a494b1736ce9b3c4fc4fc"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_all_editable","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"ae1f823f0afaa4fe7bc8e5066af64b21"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_assert_contact","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"0f8ecbc7947d1c3466f8dbc3b9b85a65"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_automation_scope","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"5472b1c38d88b653517fb5f351f9844d"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_call_fingerprint","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"dee4d5dc2bc05130cb523dd8fed44693"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_claim_original","proconfig":["search_path=pg_catalog, pg_temp"],"prosecdef":true,"definition_md5":"67d6284b543274383f50baa3815924b7"},{"owner":"agentflow_affinity_scope","proacl":["agentflow_affinity_scope=X/agentflow_affinity_scope"],"schema":"private","proname":"affinity_contact_scope","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"6f3b907b029ccf3ed35383823001702d"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_default","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"41ff1911d3b82d8bbace92b2ebc98d6c"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_disposition_guard","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"30f6ea81f3eda000b08edb5d0323e314"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_enforcement_guard","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"a0f8b0e591c4acd0b2eeb2e92aed22a6"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_enqueue_call","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"caf99582051bd5128de5c288bf35f8e5"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_ensure","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"4151dad3e99909d9ced098e547bf01a6"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_event","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"56efe0bcfcbe1ce7ae5e5f117c133919"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_finish_original","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"ba794705c11dd9510011c3ac21a26f8f"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_has_history","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"1a41f24b3207320a3e68a3f22e30ca6c"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_immutable","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"2a405f50ce37feede4bdafa56abf6914"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_ingest_original","proconfig":["search_path=pg_catalog, pg_temp"],"prosecdef":true,"definition_md5":"60ffcb78b4a4f995b2c8a70db9f0c949"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_internal_alert","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"88e6b6aeb94579f5454617f8f6ca38c1"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_lock","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"db880054f766a7b6bf1292724f26f018"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_mode","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"a95eee2ac92617075da8884e048bef30"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_number","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"04617e0576eaf471b1a52124a9293252"},{"owner":"postgres","proacl":["postgres=X/postgres","agentflow_affinity_scope=X/postgres"],"schema":"private","proname":"affinity_phone","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"70b09b08179613bbca55c223ecc69880"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_policy_guard","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"4cee247527a0960ab4bcc02b3bf85c32"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_prepare","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"408a1b60378b86511842cb706384db8e"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_prepare_original","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"7df937c18b11164e3583a7e78a6dd1d5"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_process_call","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"27bc67b3418b02c0330622e4e059a729"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_qualify_call","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"3805e35a3d4a93993472cfe1349214da"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_recover","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"e6fd9ed11f31fde43c9501f8fc86893a"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_start_original","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"df1ce5924b3071f9cd8318075337a487"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_unresolved","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"71aec0e4f05953b284aa59cd6c010741"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_view","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"267af2312e83540016c838d9b211a448"},{"owner":"postgres","proacl":["postgres=X/postgres"],"schema":"private","proname":"affinity_voice_scope","proconfig":["search_path=\"\""],"prosecdef":false,"definition_md5":"55de8731da7051ddbbec29d5f52ad702"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"admit_twilio_outbound","proconfig":["search_path=pg_catalog, pg_temp"],"prosecdef":true,"definition_md5":"149bea68ea843c4790e292fc1438b06e"},{"owner":"postgres","proacl":["postgres=X/postgres","authenticated=X/postgres"],"schema":"public","proname":"authorize_contact_call","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"8a9fbdd85739abec3d1481e2706a1ce6"},{"owner":"postgres","proacl":["postgres=X/postgres","authenticated=X/postgres"],"schema":"public","proname":"change_contact_number","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"222da881f9587c063b2b0b539aa64425"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"claim_inbound_call","proconfig":["search_path=pg_catalog, pg_temp"],"prosecdef":true,"definition_md5":"b6fa4e8f37a0763aebce01a5481dc8cd"},{"owner":"postgres","proacl":["postgres=X/postgres","authenticated=X/postgres"],"schema":"public","proname":"contact_number_modes","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"31252ba0adbdd05afd38954c5c87fb53"},{"owner":"postgres","proacl":["postgres=X/postgres","authenticated=X/postgres"],"schema":"public","proname":"contact_number_options","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"483e8da61619a8e91a661759555278d1"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"ingest_inbound_call","proconfig":["search_path=pg_catalog, pg_temp"],"prosecdef":true,"definition_md5":"dd54a243993286258ce238a95c11f08f"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"observe_contact_inbound_sms","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"d0c36acecec60ef5a369490127021649"},{"owner":"postgres","proacl":["postgres=X/postgres","authenticated=X/postgres"],"schema":"public","proname":"preview_contact_numbers","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"c3ddb20f20668cf7eb80617b3f9395bc"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"reconcile_contact_number_history","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"175a721072964959bf644dc38e4f9637"},{"owner":"postgres","proacl":["postgres=X/postgres","authenticated=X/postgres"],"schema":"public","proname":"recover_contact_numbers","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"3da099b973c0ba2998c4ffaae76a4ab4"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"set_contact_number_modes","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"4afcedfc89f6832ef0419fd95d36c9c1"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"sms_authorize_bound_dispatch","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"0db6b493dcc234cc85f16b49da2037cc"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"sms_cancel_prepared_dispatch","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"4e87adae469fca339240cc5d6cb40a23"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"sms_describe_contact_sender","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"f66b9337dc2980da634f161963860ec9"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"sms_finish_dispatch","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"5792d2ab70f0827eaaaba496bc59c3ae"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"sms_prepare_bound_dispatch","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"f01daabe724d6d8a588d25bcafc96a12"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"sms_prepare_dispatch","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"4f353abb5db7d8f9faa63ca06c3c1149"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"sms_start_dispatch","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"bf51962ddbc780300608ca84bb2d4d01"},{"owner":"postgres","proacl":["postgres=X/postgres","service_role=X/postgres"],"schema":"public","proname":"sticky_number_guard","proconfig":["search_path=\"\""],"prosecdef":true,"definition_md5":"28b2deb120b2db394745a6cfd8633f17"}]$functions$::jsonb;
 reviewed jsonb:=$dispositions$[{"id":"c6c34dd8-20d6-4e4e-8a57-729fc862870c","name":"Appointment Set","dnc_auto_add":false,"affinity_class":"unreviewed","auto_add_to_dnc":false,"callback_scheduler":false,"appointment_scheduler":true,"target":"confirmed"},{"id":"fc4f08c1-6db7-44c2-a0e2-3e211a84bbd3","name":"Call Back","dnc_auto_add":false,"affinity_class":"unreviewed","auto_add_to_dnc":false,"callback_scheduler":true,"appointment_scheduler":false,"target":"confirmed"},{"id":"47becdbd-a226-4d98-9b1c-2cfd713b674b","name":"DNC","dnc_auto_add":true,"affinity_class":"unreviewed","auto_add_to_dnc":true,"callback_scheduler":false,"appointment_scheduler":false,"target":"excluded"},{"id":"aaaaaaaa-0001-0001-0001-000000000002","name":"No Answer","dnc_auto_add":false,"affinity_class":"unreviewed","auto_add_to_dnc":false,"callback_scheduler":false,"appointment_scheduler":false,"target":"excluded"},{"id":"72c2fa48-9ad1-464e-a297-34050b9462a4","name":"Not Interested","dnc_auto_add":true,"affinity_class":"unreviewed","auto_add_to_dnc":false,"callback_scheduler":false,"appointment_scheduler":false,"target":"excluded"},{"id":"84e2ea46-d6e2-403c-b6c8-467f33c5f288","name":"Sold","dnc_auto_add":false,"affinity_class":"unreviewed","auto_add_to_dnc":false,"callback_scheduler":false,"appointment_scheduler":false,"target":"confirmed"}]$dispositions$::jsonb;
 alerts jsonb:=$alerts$[{"organization_id":"a0000000-0000-0000-0000-000000000001","key_prefix":"clearpath:lead:","actor_id":"ecf2bb91-0350-4542-85ec-14d914311e99","sender":"+19162998778","recipient":"+19097756963"},{"organization_id":"a0000000-0000-0000-0000-000000000001","key_prefix":"clearpath:test:","actor_id":"ecf2bb91-0350-4542-85ec-14d914311e99","sender":"+19162998778","recipient":"+19097756963"}]$alerts$::jsonb;
 actual_functions jsonb; current_dispositions jsonb; e jsonb; result jsonb;
 cursor_value text; scanned_count integer; review_count integer; seeded_count integer; pages integer; affected integer;
 before_messages bigint; before_dispatches bigint; before_calls bigint; mode_result jsonb; other_modes jsonb;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'activation_operator_mismatch';END IF;
 IF (SELECT count(*) FROM supabase_migrations.schema_migrations)<>386 OR (SELECT max(version) FROM supabase_migrations.schema_migrations)<>'20261120060345'
 THEN RAISE EXCEPTION 'activation_migration_drift';END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.schema,f.proname),'[]') INTO actual_functions FROM (
 SELECT n.nspname AS schema,p.proname,pg_get_userbyid(p.proowner) AS owner,p.prosecdef,p.proconfig,p.proacl,md5(pg_get_functiondef(p.oid)) AS definition_md5
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE (n.nspname='private' AND p.proname LIKE 'affinity_%') OR (n.nspname='public' AND p.proname IN
 ('preview_contact_numbers','contact_number_options','contact_number_modes','authorize_contact_call','change_contact_number','recover_contact_numbers','sticky_number_guard','sms_prepare_dispatch','sms_prepare_bound_dispatch','sms_authorize_bound_dispatch','sms_start_dispatch','sms_cancel_prepared_dispatch','sms_finish_dispatch','sms_describe_contact_sender','observe_contact_inbound_sms','reconcile_contact_number_history','set_contact_number_modes','admit_twilio_outbound','ingest_inbound_call','claim_inbound_call'))
 ) f;
 IF actual_functions IS DISTINCT FROM expected_functions THEN RAISE EXCEPTION 'activation_function_drift';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.organizations WHERE id=target_org) OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id='ecf2bb91-0350-4542-85ec-14d914311e99' AND organization_id=target_org AND status='Active' AND role='Admin') THEN RAISE EXCEPTION 'activation_target_drift';END IF;
 IF EXISTS(SELECT 1 FROM private.contact_number_settings) OR EXISTS(SELECT 1 FROM private.contact_number_enforcement)
 OR EXISTS(SELECT 1 FROM private.contact_number_reconciliation) OR EXISTS(SELECT 1 FROM private.contact_number_affinities)
 OR EXISTS(SELECT 1 FROM private.contact_number_internal_alerts) THEN RAISE EXCEPTION 'activation_initial_state_changed';END IF;
 IF EXISTS(SELECT 1 FROM public.organizations WHERE private.affinity_mode(id,'sms')<>'off' OR private.affinity_mode(id,'voice')<>'off') THEN RAISE EXCEPTION 'activation_modes_changed';END IF;
 SELECT jsonb_agg(jsonb_build_object('org',id,'voice',private.affinity_mode(id,'voice'),'sms',private.affinity_mode(id,'sms')) ORDER BY id) INTO other_modes FROM public.organizations WHERE id<>target_org;
 IF NOT EXISTS(SELECT 1 FROM public.sms_agency_policies WHERE organization_id=target_org AND enforced AND send_enabled AND cardinality(selected_phone_ids)=22) THEN RAISE EXCEPTION 'activation_sms_policy_changed';END IF;
 IF (SELECT count(*) FROM public.phone_numbers WHERE organization_id=target_org)<>22 OR EXISTS(SELECT 1 FROM public.phone_numbers WHERE organization_id=target_org AND (private.affinity_number(target_org,id,'sms')->>'readiness'<>'ready' OR private.affinity_number(target_org,id,'voice')->>'readiness'<>'ready')) THEN RAISE EXCEPTION 'activation_number_readiness_changed';END IF;
 IF EXISTS(SELECT 1 FROM public.sms_dispatches WHERE organization_id=target_org AND state IN ('prepared','attempting','uncertain'))
 OR EXISTS(SELECT 1 FROM public.sms_confirmation_jobs WHERE organization_id=target_org AND lease_until>clock_timestamp())
 OR EXISTS(SELECT 1 FROM public.calls WHERE organization_id=target_org AND created_at>clock_timestamp()-interval '30 minutes' AND status IN ('queued','initiated','ringing','in-progress'))
 THEN RAISE EXCEPTION 'activation_inflight_work';END IF;
 SELECT count(*) INTO before_messages FROM public.messages WHERE organization_id=target_org;
 SELECT count(*) INTO before_dispatches FROM public.sms_dispatches WHERE organization_id=target_org;
 SELECT count(*) INTO before_calls FROM public.calls WHERE organization_id=target_org;

 -- Guard all six reviewed identities and their existing configuration before classification.
 IF (SELECT count(*) FROM public.dispositions WHERE organization_id=target_org)<>6 THEN RAISE EXCEPTION 'activation_disposition_count_changed';END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(reviewed) LOOP
  IF NOT EXISTS(SELECT 1 FROM public.dispositions d WHERE d.organization_id=target_org AND d.id=(e->>'id')::uuid
   AND d.name=e->>'name' AND d.affinity_class=e->>'affinity_class'
   AND d.appointment_scheduler=(e->>'appointment_scheduler')::boolean AND d.callback_scheduler=(e->>'callback_scheduler')::boolean
   AND d.dnc_auto_add=(e->>'dnc_auto_add')::boolean AND d.auto_add_to_dnc=(e->>'auto_add_to_dnc')::boolean)
  THEN RAISE EXCEPTION 'activation_disposition_drift';END IF;
 END LOOP;
 UPDATE public.dispositions d SET affinity_class=e.target
 FROM jsonb_to_recordset(reviewed) AS e(id uuid,target text)
 WHERE d.organization_id=target_org AND d.id=e.id;
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>6 THEN RAISE EXCEPTION 'activation_disposition_update_count';END IF;

 -- Preserve only the already deployed, fixed-purpose ClearPath route; this sends nothing.
 IF jsonb_array_length(alerts)<>2 THEN RAISE EXCEPTION 'activation_alert_shape';END IF;
 INSERT INTO private.contact_number_internal_alerts(organization_id,key_prefix,actor_id,sender,recipient)
 SELECT organization_id,key_prefix,actor_id,sender,recipient FROM jsonb_to_recordset(alerts) AS x(organization_id uuid,key_prefix text,actor_id uuid,sender text,recipient text)
 WHERE organization_id=target_org AND actor_id='ecf2bb91-0350-4542-85ec-14d914311e99' AND key_prefix IN ('clearpath:lead:','clearpath:test:')
 AND EXISTS(SELECT 1 FROM public.phone_numbers n WHERE n.organization_id=target_org AND n.phone_number=x.sender AND private.affinity_number(target_org,n.id,'sms')->>'readiness'='ready');
 GET DIAGNOSTICS affected=ROW_COUNT;IF affected<>2 THEN RAISE EXCEPTION 'activation_alert_update_count';END IF;

 -- Actual native dry run after the exact supporting configuration, still no affinities.
 cursor_value:=NULL;scanned_count:=0;review_count:=0;seeded_count:=0;pages:=0;
 LOOP
  result:=public.reconcile_contact_number_history(target_org,cursor_value,500,true);
  pages:=pages+1;scanned_count:=scanned_count+(result->>'scanned')::integer;review_count:=review_count+(result->>'review')::integer;seeded_count:=seeded_count+(result->>'seeded')::integer;
  EXIT WHEN (result->>'complete')::boolean;
  IF pages>=10 OR result->>'cursor' IS NULL OR (cursor_value IS NOT NULL AND result->>'cursor'<=cursor_value) THEN RAISE EXCEPTION 'activation_dry_run_cursor';END IF;
  cursor_value:=result->>'cursor';
 END LOOP;
 IF scanned_count<>3183 OR review_count<>44 OR seeded_count<>2 OR pages<>7 THEN RAISE EXCEPTION 'activation_dry_run_changed: scanned %, review %, seeded %, pages %',scanned_count,review_count,seeded_count,pages;END IF;
 IF EXISTS(SELECT 1 FROM private.contact_number_affinities) OR EXISTS(SELECT 1 FROM private.contact_number_events) OR EXISTS(SELECT 1 FROM private.contact_number_reconciliation) THEN RAISE EXCEPTION 'activation_dry_run_wrote_data';END IF;

 -- Apply only what the real dry run just validated, using the installed bounded function.
 cursor_value:=NULL;scanned_count:=0;review_count:=0;seeded_count:=0;pages:=0;
 LOOP
  result:=public.reconcile_contact_number_history(target_org,cursor_value,500,false);
  pages:=pages+1;scanned_count:=scanned_count+(result->>'scanned')::integer;review_count:=review_count+(result->>'review')::integer;seeded_count:=seeded_count+(result->>'seeded')::integer;
  EXIT WHEN (result->>'complete')::boolean;
  IF pages>=10 OR result->>'cursor' IS NULL OR (cursor_value IS NOT NULL AND result->>'cursor'<=cursor_value) THEN RAISE EXCEPTION 'activation_apply_cursor';END IF;
  cursor_value:=result->>'cursor';
 END LOOP;
 IF scanned_count<>3183 OR review_count<>44 OR seeded_count<>2 OR pages<>7 THEN RAISE EXCEPTION 'activation_apply_changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM private.contact_number_reconciliation r WHERE r.organization_id=target_org AND r.complete AND r.scanned=3183 AND r.review_count=44) THEN RAISE EXCEPTION 'activation_scan_incomplete';END IF;
 IF (SELECT count(*) FROM private.contact_number_affinities WHERE organization_id=target_org)<>3183
 OR (SELECT count(*) FROM private.contact_number_affinities WHERE organization_id=target_org AND history_state='needs_review')<>44
 OR (SELECT count(*) FROM private.contact_number_affinities WHERE organization_id=target_org AND sms_state='established')<>2
 OR EXISTS(SELECT 1 FROM private.contact_number_affinities WHERE organization_id=target_org AND voice_state='established') THEN RAISE EXCEPTION 'activation_affinity_counts';END IF;

 IF (SELECT count(*) FROM public.calls WHERE organization_id=target_org)<>before_calls THEN RAISE EXCEPTION 'activation_call_activity_changed';END IF;
 mode_result:=public.set_contact_number_modes(target_org,'enforced','enforced');
 IF mode_result IS DISTINCT FROM '{"voice":"enforced","sms":"enforced"}'::jsonb THEN RAISE EXCEPTION 'activation_mode_result';END IF;
 IF other_modes IS DISTINCT FROM (SELECT jsonb_agg(jsonb_build_object('org',id,'voice',private.affinity_mode(id,'voice'),'sms',private.affinity_mode(id,'sms')) ORDER BY id) FROM public.organizations WHERE id<>target_org) THEN RAISE EXCEPTION 'activation_other_org_changed';END IF;
 IF EXISTS(SELECT 1 FROM private.contact_number_affinities WHERE organization_id<>target_org) OR EXISTS(SELECT 1 FROM private.contact_number_settings WHERE organization_id<>target_org) THEN RAISE EXCEPTION 'activation_cross_org_write';END IF;
 IF (SELECT count(*) FROM public.messages WHERE organization_id=target_org)<>before_messages OR (SELECT count(*) FROM public.sms_dispatches WHERE organization_id=target_org)<>before_dispatches OR (SELECT count(*) FROM public.calls WHERE organization_id=target_org)<>before_calls THEN RAISE EXCEPTION 'activation_communication_activity_changed';END IF;
END $activate$;
SELECT jsonb_build_object('organization_id','a0000000-0000-0000-0000-000000000001','modes',public.sticky_number_guard('a0000000-0000-0000-0000-000000000001'),'activated_at',clock_timestamp(),
 'reconciliation',(SELECT to_jsonb(r)-'cursor_phone' FROM private.contact_number_reconciliation r WHERE organization_id='a0000000-0000-0000-0000-000000000001'),
 'assignments',(SELECT count(*) FROM private.contact_number_affinities WHERE organization_id='a0000000-0000-0000-0000-000000000001'),
 'needs_review',(SELECT count(*) FROM private.contact_number_affinities WHERE organization_id='a0000000-0000-0000-0000-000000000001' AND history_state='needs_review'),
 'established_sms',(SELECT count(*) FROM private.contact_number_affinities WHERE organization_id='a0000000-0000-0000-0000-000000000001' AND sms_state='established')) AS activation;
COMMIT;
